settings.custom_liquid:
{% assign active_collection = collection %}
{% assign first_product = active_collection.products.first %}

{% if active_collection != blank and active_collection.products_count > 0 %}
  <style>
    .tjs-drop-room {
      position: relative;
      overflow: hidden;
      padding: 26px 14px 46px;
      font-family: inherit;
      background:
        radial-gradient(circle at 10% 8%, rgba(23,23,23, 0.72), transparent 28%),
        radial-gradient(circle at 86% 10%, rgba(23,23,23, 0.62), transparent 30%),
        radial-gradient(circle at 50% 90%, rgba(226, 238, 222, 0.42), transparent 34%),
        linear-gradient(135deg, #FFFFFF 0%, #FFFFFF 54%, #FFFFFF 100%);
      isolation: isolate;
    }

    .tjs-drop-room::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: 0;
      pointer-events: none;
      background:
        radial-gradient(circle, rgba(23,23,23, 0.07) 0 1px, transparent 1.8px) 0 0 / 34px 34px,
        linear-gradient(115deg, transparent 0%, rgba(255,255,255,0.36) 45%, transparent 58%);
      opacity: 0.55;
    }

    .tjs-drop-room__inner {
      position: relative;
      z-index: 1;
      max-width: 1240px;
      margin: 0 auto;
    }

    .tjs-drop-room__top {
      display: grid;
      grid-template-columns: 1fr auto;
      align-items: end;
      gap: 22px;
      margin-bottom: 24px;
      padding: 22px;
      border-radius: 30px;
      background: rgba(255,255,255,0.56);
      border: 1px solid rgba(23,23,23,0.34);
      box-shadow: 0 18px 42px rgba(47,36,32,0.075);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
    }

    .tjs-drop-room__kicker {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      margin-bottom: 10px;
      color: currentColor;
      font-size: 10px;
      line-height: 1;
      font-weight: 950;
      letter-spacing: 1.3px;
      text-transform: uppercase;
    }

    .tjs-drop-room__kicker::before {
      content: "✦";
      color: currentColor;
    }

    .tjs-drop-room__title {
      margin: 0;
      max-width: 720px;
      color: #171717;
      font-size: clamp(34px, 5vw, 66px);
      line-height: 0.92;
      letter-spacing: -2.2px;
      font-weight: 950;
    }

    .tjs-drop-room__title span {
      background: linear-gradient(115deg, #F5F5F3, #F5F5F3, #F5F5F3, #F5F5F3);
      background-size: 260% 100%;
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      animation: tjsDropGold 4s ease-in-out infinite;
    }

    @keyframes tjsDropGold {
      0%, 100% { background-position: 100% 0; }
      50% { background-position: 0 0; }
    }

    .tjs-drop-room__copy {
      margin-top: 12px;
      max-width: 620px;
      color: #656565;
      font-size: 13.5px;
      line-height: 1.65;
      font-weight: 500;
    }

    .tjs-drop-room__meta {
      display: grid;
      grid-template-columns: repeat(2, auto);
      gap: 9px;
      justify-content: end;
    }

    .tjs-drop-room__pill {
      padding: 10px 12px;
      border-radius: 999px;
      background: rgba(255,255,255,0.72);
      border: 1px solid rgba(23,23,23,0.34);
      color: currentColor;
      font-size: 11px;
      line-height: 1;
      font-weight: 900;
      white-space: nowrap;
      box-shadow: 0 10px 22px rgba(47,36,32,0.045);
    }

    .tjs-drop-room__count {
      grid-column: 1 / -1;
      padding: 13px 15px;
      border-radius: 20px;
      background: linear-gradient(135deg, #171717, #F5F5F3);
      color: #FFFFFF;
      text-align: center;
      box-shadow: 0 14px 28px rgba(47,36,32,0.16);
    }

    .tjs-drop-room__count strong {
      display: block;
      font-size: 26px;
      line-height: 1;
      font-weight: 950;
    }

    .tjs-drop-room__count span {
      display: block;
      margin-top: 4px;
      font-size: 10px;
      line-height: 1;
      font-weight: 700;
      color: rgba(255,249,243,0.72);
    }

    .tjs-drop-room__shelf {
      position: relative;
      overflow: hidden;
      padding: 22px;
      border-radius: 34px;
      background:
        linear-gradient(135deg, rgba(255,255,255,0.62), rgba(255,246,240,0.52));
      border: 1px solid rgba(23,23,23,0.32);
      box-shadow: 0 20px 50px rgba(47,36,32,0.08);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
    }

    .tjs-drop-room__shelf::before {
      content: "";
      position: absolute;
      left: 0;
      right: 0;
      bottom: 32px;
      height: 42px;
      background:
        linear-gradient(180deg, rgba(23,23,23,0.08), rgba(23,23,23,0.02));
      border-top: 1px solid rgba(23,23,23,0.12);
      border-bottom: 1px solid rgba(255,255,255,0.6);
      pointer-events: none;
    }

    .tjs-drop-room__rail {
      position: relative;
      z-index: 1;
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(220px, 1fr);
      gap: 20px;
      overflow-x: auto;
      padding: 8px 4px 26px;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      -webkit-overflow-scrolling: touch;
    }

    .tjs-drop-room__rail::-webkit-scrollbar {
      display: none;
    }

    .tjs-drop-card {
      position: relative;
      display: block;
      scroll-snap-align: start;
      text-decoration: none;
      color: inherit;
      min-width: 0;
    }

    .tjs-drop-card__cover {
      position: relative;
      aspect-ratio: 3 / 4.28;
      overflow: hidden;
      border-radius: 28px;
      background: #FFFFFF;
      border: 1px solid rgba(23,23,23,0.36);
      box-shadow:
        0 24px 44px rgba(47,36,32,0.16),
        inset 0 1px 0 rgba(255,255,255,0.9);
      transform-origin: center bottom;
      transition: transform 0.34s ease, box-shadow 0.34s ease, border-color 0.34s ease;
    }

    .tjs-drop-card:nth-child(5n+1) .tjs-drop-card__cover { transform: rotate(-1.6deg); }
    .tjs-drop-card:nth-child(5n+2) .tjs-drop-card__cover { transform: translateY(12px) rotate(1.1deg); }
    .tjs-drop-card:nth-child(5n+3) .tjs-drop-card__cover { transform: rotate(0.8deg); }
    .tjs-drop-card:nth-child(5n+4) .tjs-drop-card__cover { transform: translateY(7px) rotate(-0.8deg); }
    .tjs-drop-card:nth-child(5n+5) .tjs-drop-card__cover { transform: rotate(1.4deg); }

    .tjs-drop-card:hover .tjs-drop-card__cover {
      transform: translateY(-10px) rotate(0deg) scale(1.018);
      border-color: rgba(23,23,23,0.46);
      box-shadow:
        0 34px 66px rgba(47,36,32,0.24),
        inset 0 1px 0 rgba(255,255,255,0.94);
    }

    .tjs-drop-card__cover img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transition: transform 0.45s ease, filter 0.45s ease;
    }

    .tjs-drop-card:hover .tjs-drop-card__cover img {
      transform: scale(1.04);
      filter: saturate(1.04) contrast(1.02);
    }

    .tjs-drop-card__cover::after {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background:
        linear-gradient(180deg, transparent 0%, transparent 64%, rgba(47,36,32,0.54) 100%),
        linear-gradient(115deg, transparent 0%, transparent 42%, rgba(255,255,255,0.58) 50%, transparent 60%, transparent 100%);
      transform: translateX(-135%);
      transition: transform 0.85s ease;
    }

    .tjs-drop-card:hover .tjs-drop-card__cover::after {
      transform: translateX(135%);
    }

    .tjs-drop-card__tag {
      position: absolute;
      z-index: 3;
      top: 12px;
      left: 12px;
      padding: 7px 10px;
      border-radius: 999px;
      background: rgba(47,36,32,0.86);
      color: #FFFFFF;
      font-size: 9px;
      line-height: 1;
      font-weight: 900;
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
    }

    .tjs-drop-card__info {
      position: absolute;
      z-index: 3;
      left: 12px;
      right: 12px;
      bottom: 12px;
      padding: 11px;
      border-radius: 18px;
      background: rgba(255,255,255,0.8);
      border: 1px solid rgba(255,255,255,0.62);
      box-shadow: 0 12px 24px rgba(47,36,32,0.13);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      transform: translateY(4px);
      transition: transform 0.28s ease, background 0.28s ease;
    }

    .tjs-drop-card:hover .tjs-drop-card__info {
      transform: translateY(0);
      background: rgba(255,255,255,0.88);
    }

    .tjs-drop-card__title {
      color: #171717;
      font-size: 12px;
      line-height: 1.18;
      font-weight: 950;
      letter-spacing: -0.2px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .tjs-drop-card__bottom {
      margin-top: 7px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }

    .tjs-drop-card__price {
      color: currentColor;
      font-size: 11.5px;
      line-height: 1;
      font-weight: 950;
    }

    .tjs-drop-card__view {
      color: #171717;
      font-size: 9.5px;
      line-height: 1;
      font-weight: 950;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .tjs-drop-room__below {
      margin-top: 20px;
      display: grid;
      grid-template-columns: 1fr auto;
      align-items: center;
      gap: 14px;
    }

    .tjs-drop-room__note {
      color: #656565;
      font-size: 12px;
      line-height: 1.5;
      font-weight: 650;
    }

    .tjs-drop-room__note strong {
      color: #171717;
      font-weight: 950;
    }

    .tjs-drop-room__jump {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 42px;
      padding: 12px 17px;
      border-radius: 999px;
      background: linear-gradient(135deg, #171717, #F5F5F3);
      color: #FFFFFF;
      text-decoration: none;
      font-size: 12px;
      line-height: 1;
      font-weight: 900;
      box-shadow: 0 14px 26px rgba(47,36,32,0.15);
    }

    @media screen and (min-width: 990px) {
      .tjs-drop-room__rail {
        grid-auto-columns: calc((100% - 80px) / 5);
      }
    }

    @media screen and (max-width: 989px) {
      .tjs-drop-room__top {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .tjs-drop-room__copy,
      .tjs-drop-room__title {
        margin-left: auto;
        margin-right: auto;
      }

      .tjs-drop-room__meta {
        justify-content: center;
      }

      .tjs-drop-room__rail {
        grid-auto-columns: 32%;
      }
    }

    @media screen and (max-width: 749px) {
      .tjs-drop-room {
        padding: 14px 10px 34px;
      }

      .tjs-drop-room__top {
        padding: 18px 14px;
        border-radius: 24px;
        margin-bottom: 14px;
      }

      .tjs-drop-room__title {
        font-size: 34px;
        line-height: 0.96;
        letter-spacing: -1.3px;
      }

      .tjs-drop-room__copy {
        font-size: 12.3px;
        line-height: 1.55;
      }

      .tjs-drop-room__meta {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .tjs-drop-room__pill {
        font-size: 9.5px;
        padding: 8px 9px;
        text-align: center;
      }

      .tjs-drop-room__count strong {
        font-size: 22px;
      }

      .tjs-drop-room__shelf {
        padding: 12px;
        border-radius: 24px;
      }

      .tjs-drop-room__rail {
        grid-auto-columns: 78%;
        gap: 14px;
        padding-bottom: 18px;
      }

      .tjs-drop-card:nth-child(n) .tjs-drop-card__cover {
        transform: none;
      }

      .tjs-drop-card__cover {
        border-radius: 22px;
      }

      .tjs-drop-room__below {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .tjs-drop-room__jump {
        width: 100%;
      }
    }
  </style>

  <section class="tjs-drop-room">
    <div class="tjs-drop-room__inner">
      <div class="tjs-drop-room__top">
        <div>
          <div class="tjs-drop-room__kicker">The Undated Planner Drop</div>

          <h1 class="tjs-drop-room__title">
            Covers made for your
            <span>next era.</span>
          </h1>

          <div class="tjs-drop-room__copy">
            No dates. No pressure. Just beautifully designed planners you can start whenever life feels ready for a reset.
          </div>
        </div>

        <div class="tjs-drop-room__meta">
          <div class="tjs-drop-room__pill">Start Anytime</div>
          <div class="tjs-drop-room__pill">Free Sticker Book</div>
          <div class="tjs-drop-room__count">
            <strong>{{ active_collection.products_count }}</strong>
            <span>cover designs</span>
          </div>
        </div>
      </div>

      <div class="tjs-drop-room__shelf">
        <div class="tjs-drop-room__rail">
          {% for linked_product in active_collection.products %}
            {% assign style_title = linked_product.title
              | remove: "Undated Yearly Planner 2025 Collection"
              | remove: "Undated Yearly Planner Current State"
              | remove: "Undated Yearly Planner"
              | remove: "Undated Yealry Planner"
              | remove: "Limited Edition Undated Planner"
              | remove: "(Limited Hardbound Collection)"
              | remove: "Limited Hardbound Collection"
              | remove: "Ultimate Sticker Book"
              | remove: "+"
              | remove: "–"
              | remove: "—"
              | remove: "-"
              | strip
            %}

            {% capture linked_price %}
              {{ linked_product.price | money }}
            {% endcapture %}
            {% assign linked_price = linked_price | strip %}

            <a class="tjs-drop-card" href="{{ linked_product.url }}">
              <div class="tjs-drop-card__cover">
                <span class="tjs-drop-card__tag">Undated</span>

                {% if linked_product.featured_image %}
                  <img
                    src="{{ linked_product.featured_image | image_url: width: 800 }}"
                    alt="{{ style_title | escape }}"
                    loading="lazy"
                  >
                {% endif %}

                <div class="tjs-drop-card__info">
                  <div class="tjs-drop-card__title">
                    {{ style_title }}
                  </div>

                  <div class="tjs-drop-card__bottom">
                    <div class="tjs-drop-card__price">
                      {{ linked_price }}
                    </div>

                    <div class="tjs-drop-card__view">
                      View
                    </div>
                  </div>
                </div>
              </div>
            </a>
          {% endfor %}
        </div>

        <div class="tjs-drop-room__below">
          <div class="tjs-drop-room__note">
            <strong>Swipe the shelf</strong> to explore every planner cover design.
          </div>

          <a class="tjs-drop-room__jump" href="#MainContent">
            Continue Shopping
          </a>
        </div>
      </div>
    </div>
  </section>
{% endif %}
